def run_bounded_agent(task, decide, execute, max_steps=8):
    state = {"task": task, "history": [], "status": "running"}
    for step in range(max_steps):
        decision = decide(state)
        if decision["type"] == "finish":
            state["status"] = "completed"
            state["result"] = decision.get("result")
            return state
        if decision["type"] != "action":
            raise ValueError("Unknown decision type")
        result = execute(decision["name"], decision.get("arguments", {}))
        state["history"].append({"action": decision["name"], "result": result})
    state["status"] = "step_limit_reached"
    return state

ALLOWED = {"received": {"planning", "failed"}, "planning": {"executing", "awaiting_approval", "failed"}, "awaiting_approval": {"executing", "failed"}, "executing": {"verifying", "failed"}, "verifying": {"completed", "planning", "failed"}, "completed": set(), "failed": set()}

def transition(state, next_state):
    if next_state not in ALLOWED.get(state, set()):
        raise ValueError(f"Invalid transition: {state} -> {next_state}")
    return next_state
